CREATE TABLE category (id BIGINT PRIMARY KEY, name VARCHAR(64), slug VARCHAR(64));
CREATE TABLE tag (id BIGINT PRIMARY KEY, name VARCHAR(64));
CREATE TABLE game (
 id BIGINT PRIMARY KEY, name VARCHAR(128), english_name VARCHAR(128), slug VARCHAR(160), aliases VARCHAR(500), summary VARCHAR(500), description TEXT, developer VARCHAR(128), publisher VARCHAR(128), release_date DATE, category_id BIGINT, cover_url VARCHAR(500), banner_url VARCHAR(500), cover_hue DOUBLE, cover_chroma DOUBLE, cover_lightness DOUBLE, cover_accent VARCHAR(7), cover_color_confidence DOUBLE, cover_hue_override DOUBLE, wall_enabled BOOLEAN DEFAULT TRUE, current_version VARCHAR(64), file_size VARCHAR(64), status VARCHAR(24), view_count BIGINT DEFAULT 0, resource_click_count BIGINT DEFAULT 0, published_at TIMESTAMP, created_at TIMESTAMP, updated_at TIMESTAMP, deleted_at TIMESTAMP
);
CREATE TABLE game_tag (game_id BIGINT, tag_id BIGINT);
CREATE TABLE game_platform (id BIGINT GENERATED BY DEFAULT AS IDENTITY, game_id BIGINT, platform VARCHAR(32));
CREATE TABLE game_language (id BIGINT GENERATED BY DEFAULT AS IDENTITY, game_id BIGINT, language VARCHAR(32));
